import React from 'react';
import { format } from 'date-fns';
import './MoodEntryCard.css';

const moodLabels = {
  1: 'Very Sad',
  2: 'Sad',
  3: 'Neutral',
  4: 'Happy',
  5: 'Very Happy'
};

const energyLabels = {
  1: 'Exhausted',
  2: 'Low Energy',
  3: 'Moderate',
  4: 'Energetic',
  5: 'Very Energetic'
};

const stressLabels = {
  1: 'None',
  2: 'Minimal',
  3: 'Moderate',
  4: 'High',
  5: 'Extreme'
};

const sleepLabels = {
  1: 'Poor',
  2: 'Fair',
  3: 'Average',
  4: 'Good',
  5: 'Excellent'
};

const MoodEntryCard = ({ entry }) => {
  if (!entry) return null;
  
  const {
    mood_score,
    energy_level,
    stress_level,
    sleep_quality,
    notes,
    created_at
  } = entry;
  
  const formattedDate = created_at 
    ? format(new Date(created_at), 'PPP p') 
    : 'Date unavailable';
  
  return (
    <div className="mood-entry-card">
      <div className="mood-entry-header">
        <div className="mood-score">
          <div className="score-value">{mood_score}</div>
          <div className="score-label">{moodLabels[mood_score] || 'Unknown'}</div>
        </div>
        <div className="entry-date">{formattedDate}</div>
      </div>
      
      {notes && (
        <div className="mood-notes">
          <p>{notes}</p>
        </div>
      )}
      
      <div className="mood-factors">
        <div className="factor">
          <span className="factor-label">Energy:</span>
          <span className="factor-value">{energyLabels[energy_level] || energy_level}</span>
        </div>
        
        <div className="factor">
          <span className="factor-label">Stress:</span>
          <span className="factor-value">{stressLabels[stress_level] || stress_level}</span>
        </div>
        
        <div className="factor">
          <span className="factor-label">Sleep:</span>
          <span className="factor-value">{sleepLabels[sleep_quality] || sleep_quality}</span>
        </div>
      </div>
    </div>
  );
};

export default MoodEntryCard;
